interface DiagramNewPaneProps {
    details?: DiagramObjectDetailsService
    drawing?: DiagramEdgeDrawingService
    emphasis?: DiagramEmphasisService
    geometry?: DiagramGeometryService
    groupDrawing?: DiagramGroupDrawingService
    movement?: DiagramMoveService
    placement?: DiagramNodePlacementService
    resize?: DiagramResizeService
    review?: DiagramChangeReviewService
    selection?: DiagramSelectionService
    session?: DiagramEditSessionService
    viewService?: DiagramViewService
}

/** Owns New viewport and its floating tools so every comparison mode exposes one complete editor. */
export function DiagramNewPane({
    details = diagramObjectDetailsService,
    drawing = diagramEdgeDrawingService,
    emphasis = diagramEmphasisService,
    geometry = diagramGeometryService,
    groupDrawing = diagramGroupDrawingService,
    movement = diagramMoveService,
    placement = diagramNodePlacementService,
    resize = diagramResizeService,
    review = diagramChangeReviewService,
    selection = diagramSelectionService,
    session = diagramEditSessionService,
    viewService = diagramViewService,
}: DiagramNewPaneProps) {
    return (
        <Box sx={{ display: 'flex', flex: 1, minHeight: 0, minWidth: 0, overflow: 'hidden', position: 'relative' }}>
            <DiagramZoomViewport
                details={details}
                drawing={drawing}
                emphasis={emphasis}
                geometry={geometry}
                groupDrawing={groupDrawing}
                movement={movement}
                placement={placement}
                resize={resize}
                review={review}
                selection={selection}
                session={session}
                viewService={viewService}
            />
            <DiagramZoomSlider diagramIdentity="New" store={session} />
            <DiagramEmphasisExitButton emphasis={emphasis} surface="new" />
        </Box>
    )
}

import { Box } from '@mui/material'
import { useSyncExternalStore } from 'react'
import {
    diagramNodePlacementService,
    type DiagramNodePlacementService,
} from '../../../services/diagrams/diagram_node_placement_service'
import { DiagramNode } from '../rendering/diagram_node'

function ignorePreviewSelection() {}

/** Pointer-transparent node preview; only this leaf observes transient placement position. */
export function DiagramNodePlacementPreview({placement = diagramNodePlacementService}: {
    placement?: Pick<DiagramNodePlacementService, 'getPreviewSnapshot' | 'subscribePreview'>
}) {
    const preview = useSyncExternalStore(
        placement.subscribePreview,
        placement.getPreviewSnapshot,
        placement.getPreviewSnapshot,
    )
    if (!preview) return null

    return (
        <Box aria-hidden="true" sx={{ opacity: 0.6, pointerEvents: 'none' }}>
            <DiagramNode
                circular={preview.diagramType === 'mindmap'}
                diagramType={preview.diagramType}
                flowPreset={preview.flowPreset}
                node={{ ...preview.node, drilldown: false }}
                onSelect={ignorePreviewSelection}
                selected={false}
            />
        </Box>
    )
}

