/** Inline label and details action above one editable node. */
export function DiagramInlineNodeControls({ node, onOpenDetails, session }: {
    node: PositionedDiagramNode
    onOpenDetails: () => void
    session: DiagramEditSessionService
}) {
    const [draftState, setDraftState] = useState({ base: node.label, value: node.label })
    const draft = draftState.base === node.label ? draftState.value : node.label
    const [error, setError] = useState<string | null>(null)
    const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
        setDraftState({ base: node.label, value: event.target.value })
        setError(null)
    }
    const commit = () => {
        if (draft.trim() === node.label) return
        if (!draft.trim()) {
            setError('Label is required.')

            return
        }
        if (!session.setNodeField(node.id, 'label', draft.trim())) setError('Label could not be saved.')
    }
    const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
        if (event.key === 'Escape') {
            event.stopPropagation()
            setDraftState({ base: node.label, value: node.label })
            setError(null)

            return
        }
        if (event.key !== 'Enter') return
        event.preventDefault()
        commit()
    }
    const stopPointer = (event: PointerEvent<HTMLElement>) => event.stopPropagation()
    const stopClick = (event: MouseEvent<HTMLElement>) => event.stopPropagation()
    const handleDoubleClick = (event: MouseEvent<HTMLElement>) => {
        event.stopPropagation()
        onOpenDetails()
    }

    return (
        <Box
            className="diagram-node-inline-controls"
            onClick={stopClick}
            onDoubleClick={handleDoubleClick}
            onPointerDown={stopPointer}
            sx={{
                height: node.height, left: node.x, pointerEvents: 'none', position: 'absolute', top: node.y,
                width: node.width, zIndex: 3,
                '& .diagram-node-details-action': { opacity: 0 },
                '&:hover .diagram-node-details-action, &:focus-within .diagram-node-details-action': { opacity: 1 },
                '@media (hover: none)': { '& .diagram-node-details-action': { opacity: 1 } },
            }}
        >
            <TextField
                error={!!error}
                helperText={error}
                onBlur={commit}
                onChange={handleChange}
                onKeyDown={handleKeyDown}
                size="small"
                slotProps={{ htmlInput: { 'aria-label': `Edit ${node.label} label` } }}
                sx={{
                    left: 8, maxWidth: 'calc(100% - 48px)', pointerEvents: 'auto', position: 'absolute',
                    top: node.height / 2 - 18,
                    '& .MuiInputBase-root': { bgcolor: 'background.paper' },
                }}
                value={draft}
                variant="standard"
            />
            <Tooltip title={`Details for ${node.label}`}>
                <IconButton
                    aria-label={`Details for ${node.label}`}
                    className="diagram-node-details-action"
                    onClick={onOpenDetails}
                    size="small"
                    sx={{ pointerEvents: 'auto', position: 'absolute', right: 2, top: 2 }}
                >
                    <MoreHorizOutlined fontSize="small" />
                </IconButton>
            </Tooltip>
        </Box>
    )
}

export interface DiagramClientPoint {
    clientX: number;
    clientY: number;
}

export interface DiagramViewportMetrics {
    bounds: {
        left: number;
        top: number;
    };
    scrollLeft: number;
    scrollTop: number;
}

export interface DiagramPoint {
    x: number;
    y: number;
}

export interface DiagramCoordinateConversion {
    diagramPoint: DiagramPoint;
    viewportPoint: DiagramPoint;
}

function requireFiniteCoordinate(value: number, name: string) {
    if (!Number.isFinite(value)) throw new Error(`${name} must be finite`);
}

/** Converts one client-space pointer through its viewport into canonical diagram coordinates. */
export function convertClientToDiagramCoordinates(
    clientPoint: DiagramClientPoint,
    viewportMetrics: DiagramViewportMetrics,
    viewportScale: number,
): DiagramCoordinateConversion {
    requireFiniteCoordinate(clientPoint.clientX, 'Client x');
    requireFiniteCoordinate(clientPoint.clientY, 'Client y');
    requireFiniteCoordinate(viewportMetrics.bounds.left, 'Viewport left');
    requireFiniteCoordinate(viewportMetrics.bounds.top, 'Viewport top');
    requireFiniteCoordinate(viewportMetrics.scrollLeft, 'Viewport scroll left');
    requireFiniteCoordinate(viewportMetrics.scrollTop, 'Viewport scroll top');
    if (!Number.isFinite(viewportScale) || viewportScale <= 0) throw new Error('Viewport scale must be positive and finite');

    const viewportPoint = {
        x: clientPoint.clientX - viewportMetrics.bounds.left + viewportMetrics.scrollLeft,
        y: clientPoint.clientY - viewportMetrics.bounds.top + viewportMetrics.scrollTop,
    };
    const diagramPoint = {
        x: viewportPoint.x / viewportScale,
        y: viewportPoint.y / viewportScale,
    };

    return { diagramPoint, viewportPoint };
}

